// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 d, uint256 e) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        e = bound(e, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0);
        vm.assume(e > 0);
        vm.assume(address(this).balance >= d + e);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Deposit{value: e}() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore + e && address(c).balance == ethBefore + e);
    }

    function testFuzz_run(uint256 d, uint256 e) public {
        _run(d, e);
    }

    receive() external payable {}
}
